1	/**
2	 * Página de Conferência & Recebimento — exclusiva para lojistas.
3	 *
4	 * Lista as requisições da loja do usuário logado. Para cada requisição:
5	 *  - Exibe progresso de conferência (itens conferidos/total)
6	 *  - Permite rastrear expedição via StoreExpeditionTracker
7	 *  - Permite conferir chegada via RequisicaoChegadaModal (com o fix anti-double-count)
8	 *
9	 * Filtro: requisicoes.loja_solicitante ilike '%{nome da loja}%'
10	 * Loja ativa: StoreContext → selectedStore
11	 */
12	import { useState } from "react";
13	import { useQuery } from "@tanstack/react-query";
14	import { Loader2, Package, PackageCheck, RefreshCw, ScanBarcode, Truck } from "lucide-react";
15	import { format } from "date-fns";
16	import { ptBR } from "date-fns/locale";
17	import { toast } from "sonner";
18	
19	import { MommaPageLayout } from "@/shared/ui/MommaPageLayout";
20	import { Button } from "@/shared/ui/button";
21	import { cn } from "@/shared/lib/utils";
22	import { supabase } from "@/integrations/supabase/client";
23	import { useStore } from "@/shared/contexts/StoreContext";
24	import { normalizeRequisicaoStatus } from "@/shared/lib/logistics-utils";
25	
26	import { StoreExpeditionTracker } from "@/features/logistica";
27	import { type ChegadaItem, RequisicaoChegadaModal } from "./RequisicaoChegadaModal";
28	
29	// ─── Tipos internos ────────────────────────────────────────────────────────────
30	
31	interface RequisicaoItemRaw {
32	  id: number;
33	  nome_produto: string;
34	  produto_master_id: number | null;
35	  quantidade_solicitada: number | null;
36	  quantidade_enviada: string | null;
37	  quantidade_recebida: string | null;
38	  recebida_via: string | null;
39	  recebida_at: string | null;
40	}
41	
42	interface RequisicaoRaw {
43	  id: number;
44	  nome: string;
45	  status: string;
46	  loja_solicitante: string;
47	  created_at: string;
48	  expedicao_id: string | null;
49	  chegada_concluida_at: string | null;
50	  requisicoes_itens: RequisicaoItemRaw[];
51	}
52	
53	interface ExpeditionState {
54	  expeditionId: string;
55	  storeName: string;
56	}
57	
58	// ─── Helpers ───────────────────────────────────────────────────────────────────
59	
60	function calcProgresso(items: RequisicaoItemRaw[]) {
61	  const total = items.length;
62	  const conferidos = items.filter(
63	    (i) => (Number(i.quantidade_recebida || 0) || 0) > 0,
64	  ).length;
65	  return { total, conferidos };
66	}
67	
68	function toChegadaItems(items: RequisicaoItemRaw[]): ChegadaItem[] {
69	  return items.map((item) => ({
70	    id: item.id,
71	    nome_produto: item.nome_produto,
72	    masterId: item.produto_master_id,
73	    quantidade_solicitada: item.quantidade_solicitada ?? 0,
74	    quantidade_enviada: String(item.quantidade_enviada ?? 0),
75	    quantidade_recebida: String(item.quantidade_recebida ?? 0),
76	    recebida_via: item.recebida_via as "bip" | "manual" | null,
77	    recebida_at: item.recebida_at,
78	  }));
79	}
80	
81	type BadgeStatus = "recebida" | "expedida" | "separando" | "aguardando";
82	
83	function resolverBadgeStatus(req: RequisicaoRaw): BadgeStatus {
84	  if (req.chegada_concluida_at) return "recebida";
85	  const norm = normalizeRequisicaoStatus(req.status);
86	  if (norm === "finalizada") return "expedida";
87	  if (norm === "em_progresso") return "separando";
88	  return "aguardando";
89	}
90	
91	function StatusBadge({ status }: { status: BadgeStatus }) {
92	  const map: Record<BadgeStatus, { label: string; className: string }> = {
93	    recebida: {
94	      label: "Recebida",
95	      className: "text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20",
96	    },
97	    expedida: {
98	      label: "Expedida",
99	      className: "text-blue-600 bg-blue-50 dark:bg-blue-900/20",
100	    },
101	    separando: {
102	      label: "Separando",
103	      className: "text-amber-600 bg-amber-50 dark:bg-amber-900/20",
104	    },
105	    aguardando: {
106	      label: "Aguardando",
107	      className: "text-gray-500 bg-gray-50 dark:bg-gray-900/20",
108	    },
109	  };
110	  const { label, className } = map[status];
111	  return (
112	    <span
113	      className={cn(
114	        "inline-block px-2 py-0.5 rounded-full text-[11px] font-semibold uppercase tracking-wider",
115	        className,
116	      )}
117	    >
118	      {label}
119	    </span>
120	  );
121	}
122	
123	// ─── Card de requisição ────────────────────────────────────────────────────────
124	
125	interface RequisicaoCardProps {
126	  req: RequisicaoRaw;
127	  onRastrear: () => void;
128	  onConferir: () => void;
129	}
130	
131	function RequisicaoCard({ req, onRastrear, onConferir }: RequisicaoCardProps) {
132	  const { total, conferidos } = calcProgresso(req.requisicoes_itens);
133	  const badgeStatus = resolverBadgeStatus(req);
134	  const pct = total > 0 ? Math.min(100, Math.round((conferidos / total) * 100)) : 0;
135	  const dataFormatada = format(new Date(req.created_at), "dd/MM/yyyy", { locale: ptBR });
136	  const temExpedicao = !!req.expedicao_id;
137	
138	  return (
139	    <div className="bg-white/60 dark:bg-black/20 backdrop-blur-md border border-white/30 dark:border-white/10 rounded-2xl p-4 shadow-sm hover:shadow-md transition-shadow">
140	      {/* Linha 1: nome + status */}
141	      <div className="flex items-start justify-between gap-2 mb-2">
142	        <h3 className="text-sm font-bold text-[#2D362E] dark:text-[#E6DCCF] leading-tight flex-1 min-w-0 truncate">
143	          {req.nome}
144	        </h3>
145	        <StatusBadge status={badgeStatus} />
146	      </div>
147	
148	      {/* Linha 2: data + progresso */}
149	      <div className="flex items-center justify-between gap-2 mb-2">
150	        <p className="text-[11px] text-muted-foreground">{dataFormatada}</p>
151	        {total > 0 && (
152	          <p className="text-[11px] text-muted-foreground tabular-nums">
153	            <span className={cn("font-semibold", conferidos === total ? "text-emerald-600" : "text-[#57715B]")}>
154	              {conferidos}
155	            </span>
156	            /{total} itens conferidos
157	          </p>
158	        )}
159	      </div>
160	
161	      {/* Linha 3: barra de progresso */}
162	      {total > 0 && (
163	        <div className="w-full h-1.5 bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden mb-3">
164	          <div
165	            className={cn(
166	              "h-full rounded-full transition-all duration-500",
167	              conferidos === total ? "bg-emerald-500" : "bg-[#57715B]",
168	            )}
169	            style={{ width: `${pct}%` }}
170	          />
171	        </div>
172	      )}
173	
174	      {/* Linha 4: botões de ação */}
175	      <div className="flex gap-2">
176	        <Button
177	          data-mia-action="rastrear-expedicao"
178	          size="sm"
179	          variant="outline"
180	          disabled={!temExpedicao}
181	          title={temExpedicao ? "Rastrear expedição" : "Sem expedição vinculada"}
182	          onClick={onRastrear}
183	          className={cn(
184	            "h-9 gap-1.5 flex-1 text-[12px] border-[#57715B]/20",
185	            temExpedicao
186	              ? "hover:bg-[#57715B]/10 text-[#57715B]"
187	              : "opacity-50 cursor-not-allowed",
188	          )}
189	        >
190	          <Truck className="w-3.5 h-3.5" />
191	          Rastrear
192	        </Button>
193	        <Button
194	          data-mia-action="conferir-chegada"
195	          size="sm"
196	          onClick={onConferir}
197	          className="h-9 gap-1.5 flex-1 text-[12px] bg-[#57715B] hover:bg-[#465b49] text-white"
198	        >
199	          <ScanBarcode className="w-3.5 h-3.5" />
200	          Conferir chegada
201	        </Button>
202	      </div>
203	    </div>
204	  );
205	}
206	
207	// ─── Página principal ──────────────────────────────────────────────────────────
208	
209	export function ConferenciaRecebimentoPage() {
210	  const { selectedStore } = useStore();
211	  const [expeditionOpen, setExpeditionOpen] = useState<ExpeditionState | null>(null);
212	  const [chegadaOpen, setChegadaOpen] = useState<RequisicaoRaw | null>(null);
213	
214	  const lojaLabel = selectedStore?.name ?? "";
215	
216	  const {
217	    data: requisicoes,
218	    isLoading,
219	    error,
220	    refetch,
221	  } = useQuery<RequisicaoRaw[]>({
222	    queryKey: ["conferencia-requisicoes", selectedStore?.id],
223	    queryFn: async () => {
224	      if (!lojaLabel) return [];
225	
226	      const { data, error: queryErr } = await supabase
227	        .from("requisicoes")
228	        .select(
229	          `id, nome, status, loja_solicitante, created_at, expedicao_id, chegada_concluida_at,
230	           requisicoes_itens (
231	             id, nome_produto, produto_master_id, quantidade_solicitada,
232	             quantidade_enviada, quantidade_recebida, recebida_via, recebida_at
233	           )`,
234	        )
235	        .ilike("loja_solicitante", `%${lojaLabel}%`)
236	        .order("created_at", { ascending: false })
237	        .limit(50);
238	
239	      if (queryErr) throw queryErr;
240	
241	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
242	      return (data ?? []) as any as RequisicaoRaw[];
243	    },
244	    enabled: !!selectedStore,
245	  });
246	
247	  const handleRefetch = () => {
248	    void refetch().catch(() => toast.error("Erro ao recarregar"));
249	  };
250	
251	  return (
252	    <MommaPageLayout>
253	      <div className="max-w-3xl mx-auto px-4 py-6">
254	        {/* Header */}
255	        <div className="flex items-center justify-between gap-3 mb-6">
256	          <div className="flex items-center gap-3">
257	            <div className="rounded-2xl bg-[#57715B]/10 p-3">
258	              <PackageCheck className="h-6 w-6 text-[#57715B]" />
259	            </div>
260	            <div>
261	              <h1 className="text-2xl md:text-3xl font-bold tracking-tight font-serif text-[#2D362E] dark:text-[#E6DCCF]">
262	                Conferência & Recebimento
263	              </h1>
264	              <p className="text-xs uppercase tracking-widest text-muted-foreground">
265	                Receba e confira entregas da fábrica
266	              </p>
267	            </div>
268	          </div>
269	          <Button
270	            data-mia-action="recarregar"
271	            variant="ghost"
272	            size="icon"
273	            onClick={handleRefetch}
274	            disabled={isLoading}
275	            className="rounded-2xl h-10 w-10 hover:bg-[#57715B]/10 text-[#57715B] flex-shrink-0"
276	            title="Recarregar"
277	          >
278	            <RefreshCw className={cn("w-4 h-4", isLoading && "animate-spin")} />
279	          </Button>
280	        </div>
281	
282	        {/* Estado de erro */}
283	        {error && (
284	          <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800/30 rounded-2xl p-4 mb-4 text-red-700 dark:text-red-400 text-sm">
285	            Erro ao carregar requisições. Tente recarregar.
286	          </div>
287	        )}
288	
289	        {/* Loading */}
290	        {isLoading && (
291	          <div className="flex flex-col items-center justify-center py-20 gap-3">
292	            <Loader2 className="w-8 h-8 text-[#57715B] animate-spin" />
293	            <p className="text-sm text-muted-foreground">Carregando requisições…</p>
294	          </div>
295	        )}
296	
297	        {/* Empty state */}
298	        {!isLoading && !error && (requisicoes?.length ?? 0) === 0 && (
299	          <div className="flex flex-col items-center justify-center py-20 gap-3">
300	            <div className="rounded-2xl bg-[#57715B]/10 p-5">
301	              <Package className="w-10 h-10 text-[#57715B]/60" />
302	            </div>
303	            <p className="text-base font-semibold text-[#2D362E] dark:text-[#E6DCCF]">
304	              Nenhuma requisição encontrada
305	            </p>
306	            <p className="text-sm text-muted-foreground text-center max-w-xs">
307	              Quando a fábrica preparar pedidos para esta loja, eles aparecerão aqui.
308	            </p>
309	          </div>
310	        )}
311	
312	        {/* Grid de cards */}
313	        {!isLoading && (requisicoes?.length ?? 0) > 0 && (
314	          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
315	            {(requisicoes ?? []).map((req) => (
316	              <RequisicaoCard
317	                key={req.id}
318	                req={req}
319	                onRastrear={() => {
320	                  if (!req.expedicao_id) return;
321	                  setExpeditionOpen({
322	                    expeditionId: req.expedicao_id,
323	                    storeName: selectedStore?.name ?? "",
324	                  });
325	                }}
326	                onConferir={() => setChegadaOpen(req)}
327	              />
328	            ))}
329	          </div>
330	        )}
331	      </div>
332	
333	      {/* Modal: Rastrear expedição */}
334	      {expeditionOpen && (
335	        <StoreExpeditionTracker
336	          isOpen
337	          onClose={() => setExpeditionOpen(null)}
338	          expeditionId={expeditionOpen.expeditionId}
339	          storeName={expeditionOpen.storeName}
340	        />
341	      )}
342	
343	      {/* Modal: Conferir chegada */}
344	      {chegadaOpen && (
345	        <RequisicaoChegadaModal
346	          isOpen
347	          onClose={() => setChegadaOpen(null)}
348	          requisicaoId={chegadaOpen.id}
349	          requisicaoNome={chegadaOpen.nome}
350	          lojaDestinoId={selectedStore?.id ?? 0}
351	          lojaDestinoNome={selectedStore?.name ?? ""}
352	          items={toChegadaItems(chegadaOpen.requisicoes_itens)}
353	          onConcluida={() => {
354	            void refetch();
355	            setChegadaOpen(null);
356	          }}
357	        />
358	      )}
359	    </MommaPageLayout>
360	  );
361	}
362	
363	export default ConferenciaRecebimentoPage;
364

