/**
 * Página de Conferência & Recebimento — exclusiva para lojistas.
 *
 * Lista as requisições da loja do usuário logado. Para cada requisição:
 *  - Exibe progresso de conferência (itens conferidos/total)
 *  - Permite rastrear expedição via StoreExpeditionTracker
 *  - Permite conferir chegada via RequisicaoChegadaModal (com o fix anti-double-count)
 *
 * Filtro: requisicoes.loja_solicitante ilike '%{nome da loja}%'
 * Loja ativa: StoreContext → selectedStore
 */
import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Loader2, Package, PackageCheck, RefreshCw, ScanBarcode, Truck } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { toast } from "sonner";

import { MommaPageLayout } from "@/shared/ui/MommaPageLayout";
import { Button } from "@/shared/ui/button";
import { cn } from "@/shared/lib/utils";
import { supabase } from "@/integrations/supabase/client";
import { useStore } from "@/shared/contexts/StoreContext";
import { normalizeRequisicaoStatus } from "@/shared/lib/logistics-utils";

import { StoreExpeditionTracker } from "@/features/logistica";
import { type ChegadaItem, RequisicaoChegadaModal } from "./RequisicaoChegadaModal";

// ─── Tipos internos ────────────────────────────────────────────────────────────

interface RequisicaoItemRaw {
  id: number;
  nome_produto: string;
  produto_master_id: number | null;
  quantidade_solicitada: number | null;
  quantidade_enviada: string | null;
  quantidade_recebida: string | null;
  recebida_via: string | null;
  recebida_at: string | null;
}

interface RequisicaoRaw {
  id: number;
  nome: string;
  status: string;
  loja_solicitante: string;
  created_at: string;
  expedicao_id: string | null;
  chegada_concluida_at: string | null;
  requisicoes_itens: RequisicaoItemRaw[];
}

interface ExpeditionState {
  expeditionId: string;
  storeName: string;
}

// ─── Helpers ───────────────────────────────────────────────────────────────────

function calcProgresso(items: RequisicaoItemRaw[]) {
  const total = items.length;
  const conferidos = items.filter(
    (i) => (Number(i.quantidade_recebida || 0) || 0) > 0,
  ).length;
  return { total, conferidos };
}

function toChegadaItems(items: RequisicaoItemRaw[]): ChegadaItem[] {
  return items.map((item) => ({
    id: item.id,
    nome_produto: item.nome_produto,
    masterId: item.produto_master_id,
    quantidade_solicitada: item.quantidade_solicitada ?? 0,
    quantidade_enviada: String(item.quantidade_enviada ?? 0),
    quantidade_recebida: String(item.quantidade_recebida ?? 0),
    recebida_via: item.recebida_via as "bip" | "manual" | null,
    recebida_at: item.recebida_at,
  }));
}

type BadgeStatus = "recebida" | "expedida" | "separando" | "aguardando";

function resolverBadgeStatus(req: RequisicaoRaw): BadgeStatus {
  if (req.chegada_concluida_at) return "recebida";
  const norm = normalizeRequisicaoStatus(req.status);
  if (norm === "finalizada") return "expedida";
  if (norm === "em_progresso") return "separando";
  return "aguardando";
}

function StatusBadge({ status }: { status: BadgeStatus }) {
  const map: Record<BadgeStatus, { label: string; className: string }> = {
    recebida: {
      label: "Recebida",
      className: "text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20",
    },
    expedida: {
      label: "Expedida",
      className: "text-blue-600 bg-blue-50 dark:bg-blue-900/20",
    },
    separando: {
      label: "Separando",
      className: "text-amber-600 bg-amber-50 dark:bg-amber-900/20",
    },
    aguardando: {
      label: "Aguardando",
      className: "text-gray-500 bg-gray-50 dark:bg-gray-900/20",
    },
  };
  const { label, className } = map[status];
  return (
    <span
      className={cn(
        "inline-block px-2 py-0.5 rounded-full text-[11px] font-semibold uppercase tracking-wider",
        className,
      )}
    >
      {label}
    </span>
  );
}

// ─── Card de requisição ────────────────────────────────────────────────────────

interface RequisicaoCardProps {
  req: RequisicaoRaw;
  onRastrear: () => void;
  onConferir: () => void;
}

function RequisicaoCard({ req, onRastrear, onConferir }: RequisicaoCardProps) {
  const { total, conferidos } = calcProgresso(req.requisicoes_itens);
  const badgeStatus = resolverBadgeStatus(req);
  const pct = total > 0 ? Math.min(100, Math.round((conferidos / total) * 100)) : 0;
  const dataFormatada = format(new Date(req.created_at), "dd/MM/yyyy", { locale: ptBR });
  const temExpedicao = !!req.expedicao_id;

  return (
    <div className="bg-white/60 dark:bg-black/20 backdrop-blur-md border border-white/30 dark:border-white/10 rounded-2xl p-4 shadow-sm hover:shadow-md transition-shadow">
      {/* Linha 1: nome + status */}
      <div className="flex items-start justify-between gap-2 mb-2">
        <h3 className="text-sm font-bold text-[#2D362E] dark:text-[#E6DCCF] leading-tight flex-1 min-w-0 truncate">
          {req.nome}
        </h3>
        <StatusBadge status={badgeStatus} />
      </div>

      {/* Linha 2: data + progresso */}
      <div className="flex items-center justify-between gap-2 mb-2">
        <p className="text-[11px] text-muted-foreground">{dataFormatada}</p>
        {total > 0 && (
          <p className="text-[11px] text-muted-foreground tabular-nums">
            <span className={cn("font-semibold", conferidos === total ? "text-emerald-600" : "text-[#57715B]")}>
              {conferidos}
            </span>
            /{total} itens conferidos
          </p>
        )}
      </div>

      {/* Linha 3: barra de progresso */}
      {total > 0 && (
        <div className="w-full h-1.5 bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden mb-3">
          <div
            className={cn(
              "h-full rounded-full transition-all duration-500",
              conferidos === total ? "bg-emerald-500" : "bg-[#57715B]",
            )}
            style={{ width: `${pct}%` }}
          />
        </div>
      )}

      {/* Linha 4: botões de ação */}
      <div className="flex gap-2">
        <Button
          data-mia-action="rastrear-expedicao"
          size="sm"
          variant="outline"
          disabled={!temExpedicao}
          title={temExpedicao ? "Rastrear expedição" : "Sem expedição vinculada"}
          onClick={onRastrear}
          className={cn(
            "h-9 gap-1.5 flex-1 text-[12px] border-[#57715B]/20",
            temExpedicao
              ? "hover:bg-[#57715B]/10 text-[#57715B]"
              : "opacity-50 cursor-not-allowed",
          )}
        >
          <Truck className="w-3.5 h-3.5" />
          Rastrear
        </Button>
        <Button
          data-mia-action="conferir-chegada"
          size="sm"
          onClick={onConferir}
          className="h-9 gap-1.5 flex-1 text-[12px] bg-[#57715B] hover:bg-[#465b49] text-white"
        >
          <ScanBarcode className="w-3.5 h-3.5" />
          Conferir chegada
        </Button>
      </div>
    </div>
  );
}

// ─── Página principal ──────────────────────────────────────────────────────────

export function ConferenciaRecebimentoPage() {
  const { selectedStore } = useStore();
  const [expeditionOpen, setExpeditionOpen] = useState<ExpeditionState | null>(null);
  const [chegadaOpen, setChegadaOpen] = useState<RequisicaoRaw | null>(null);

  const lojaLabel = selectedStore?.name ?? "";

  const {
    data: requisicoes,
    isLoading,
    error,
    refetch,
  } = useQuery<RequisicaoRaw[]>({
    queryKey: ["conferencia-requisicoes", selectedStore?.id],
    queryFn: async () => {
      if (!lojaLabel) return [];

      const { data, error: queryErr } = await supabase
        .from("requisicoes")
        .select(
          `id, nome, status, loja_solicitante, created_at, expedicao_id, chegada_concluida_at,
           requisicoes_itens (
             id, nome_produto, produto_master_id, quantidade_solicitada,
             quantidade_enviada, quantidade_recebida, recebida_via, recebida_at
           )`,
        )
        .ilike("loja_solicitante", `%${lojaLabel}%`)
        .order("created_at", { ascending: false })
        .limit(50);

      if (queryErr) throw queryErr;

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      return (data ?? []) as any as RequisicaoRaw[];
    },
    enabled: !!selectedStore,
  });

  const handleRefetch = () => {
    void refetch().catch(() => toast.error("Erro ao recarregar"));
  };

  return (
    <MommaPageLayout>
      <div className="max-w-3xl mx-auto px-4 py-6">
        {/* Header */}
        <div className="flex items-center justify-between gap-3 mb-6">
          <div className="flex items-center gap-3">
            <div className="rounded-2xl bg-[#57715B]/10 p-3">
              <PackageCheck className="h-6 w-6 text-[#57715B]" />
            </div>
            <div>
              <h1 className="text-2xl md:text-3xl font-bold tracking-tight font-serif text-[#2D362E] dark:text-[#E6DCCF]">
                Conferência & Recebimento
              </h1>
              <p className="text-xs uppercase tracking-widest text-muted-foreground">
                Receba e confira entregas da fábrica
              </p>
            </div>
          </div>
          <Button
            data-mia-action="recarregar"
            variant="ghost"
            size="icon"
            onClick={handleRefetch}
            disabled={isLoading}
            className="rounded-2xl h-10 w-10 hover:bg-[#57715B]/10 text-[#57715B] flex-shrink-0"
            title="Recarregar"
          >
            <RefreshCw className={cn("w-4 h-4", isLoading && "animate-spin")} />
          </Button>
        </div>

        {/* Estado de erro */}
        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800/30 rounded-2xl p-4 mb-4 text-red-700 dark:text-red-400 text-sm">
            Erro ao carregar requisições. Tente recarregar.
          </div>
        )}

        {/* Loading */}
        {isLoading && (
          <div className="flex flex-col items-center justify-center py-20 gap-3">
            <Loader2 className="w-8 h-8 text-[#57715B] animate-spin" />
            <p className="text-sm text-muted-foreground">Carregando requisições…</p>
          </div>
        )}

        {/* Empty state */}
        {!isLoading && !error && (requisicoes?.length ?? 0) === 0 && (
          <div className="flex flex-col items-center justify-center py-20 gap-3">
            <div className="rounded-2xl bg-[#57715B]/10 p-5">
              <Package className="w-10 h-10 text-[#57715B]/60" />
            </div>
            <p className="text-base font-semibold text-[#2D362E] dark:text-[#E6DCCF]">
              Nenhuma requisição encontrada
            </p>
            <p className="text-sm text-muted-foreground text-center max-w-xs">
              Quando a fábrica preparar pedidos para esta loja, eles aparecerão aqui.
            </p>
          </div>
        )}

        {/* Grid de cards */}
        {!isLoading && (requisicoes?.length ?? 0) > 0 && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {(requisicoes ?? []).map((req) => (
              <RequisicaoCard
                key={req.id}
                req={req}
                onRastrear={() => {
                  if (!req.expedicao_id) return;
                  setExpeditionOpen({
                    expeditionId: req.expedicao_id,
                    storeName: selectedStore?.name ?? "",
                  });
                }}
                onConferir={() => setChegadaOpen(req)}
              />
            ))}
          </div>
        )}
      </div>

      {/* Modal: Rastrear expedição */}
      {expeditionOpen && (
        <StoreExpeditionTracker
          isOpen
          onClose={() => setExpeditionOpen(null)}
          expeditionId={expeditionOpen.expeditionId}
          storeName={expeditionOpen.storeName}
        />
      )}

      {/* Modal: Conferir chegada */}
      {chegadaOpen && (
        <RequisicaoChegadaModal
          isOpen
          onClose={() => setChegadaOpen(null)}
          requisicaoId={chegadaOpen.id}
          requisicaoNome={chegadaOpen.nome}
          lojaDestinoId={selectedStore?.id ?? 0}
          lojaDestinoNome={selectedStore?.name ?? ""}
          items={toChegadaItems(chegadaOpen.requisicoes_itens)}
          onConcluida={() => {
            void refetch();
            setChegadaOpen(null);
          }}
        />
      )}
    </MommaPageLayout>
  );
}

export default ConferenciaRecebimentoPage;

content.content:
1	/**
2	 * Modal de conferência de CHEGADA na loja (espelho da expedição).
3	 *
4	 * Quando o caminhão chega na loja destino, o operador entra com a requisição
5	 * carregada (apenas itens da requisição da própria loja). Para cada item:
6	 *  - Bipa o QR da caixa → RPC marcar_conferencia_requisicao(uid, requisicaoId, lojaId, meta)
7	 *    APENAS MARCAÇÃO — não mexe em estoque. Atualiza requisicoes_itens.quantidade_recebida.
8	 *  - OU marca manual (sem etiqueta): apenas atualiza recebida_via='manual'
9	 *    + quantidade_recebida = quantidade_solicitada (sem mexer em movimentacoes).
10	 *
11	 * Ao clicar "Finalizar e dar entrada": chama dar_entrada_requisicao(requisicaoId) UMA vez,
12	 * que gera as movimentacoes de estoque de todas as etiquetas bipadas (idempotente).
13	 *
14	 * Salva parcial. Operador pode fechar e voltar depois — state hidrata da DB.
15	 */
16	import { useEffect, useMemo, useRef, useState } from "react";
17	import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
18	import { Button } from "@/shared/ui/button";
19	import { Input } from "@/shared/ui/input";
20	import { ScrollArea } from "@/shared/ui/scroll-area";
21	import {
22	  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
23	  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
24	} from "@/shared/ui/alert-dialog";
25	import {
26	  ArrowLeft, Bluetooth, Camera, ScanBarcode, Package, MapPin, CheckCircle2,
27	  AlertTriangle, Hand, Boxes,
28	} from "lucide-react";
29	import { toast } from "sonner";
30	import { cn } from "@/shared/lib/utils";
31	import { supabase } from "@/integrations/supabase/client";
32	import {
33	  useEtiquetaScanner, playSuccessSound, playErrorSound, playWarningSound,
34	  type ScannedPayload,
35	} from "@/shared/hooks/useEtiquetaScanner";
36	import { CameraScannerStatus } from "@/features/logistica/ui/CameraScannerStatus";
37	
38	export interface ChegadaItem {
39	  id: number; // id em requisicoes_itens
40	  nome_produto: string;
41	  masterId: number | null;
42	  quantidade_solicitada: number;
43	  quantidade_enviada: string; // o que foi expedido pela fábrica
44	  quantidade_recebida: string; // estado persistido (parcial entre sessões)
45	  recebida_via: "bip" | "manual" | null;
46	  recebida_at: string | null;
47	}
48	
49	interface BipBuffer {
50	  itemId: number;
51	  uid: string;
52	  qty: number;
53	  embalagem: string | null;
54	  bipadoAt: number;
55	}
56	
57	interface ManualState {
58	  open: boolean;
59	  item?: ChegadaItem;
60	  quantidade: string;
61	}
62	
63	interface Props {
64	  isOpen: boolean;
65	  onClose: () => void;
66	  requisicaoId: number;
67	  requisicaoNome: string;
68	  lojaDestinoId: number;
69	  lojaDestinoNome: string;
70	  items: ChegadaItem[];
71	  /** Quando o operador clica em "Finalizar e dar entrada" — pai recarrega/atualiza UI. */
72	  onConcluida?: () => void;
73	}
74	
75	interface DarEntradaResult {
76	  ok: boolean;
77	  etiquetas_processadas: number;
78	  total_quantidade: number;
79	  ja_processadas: number;
80	  alertas: string[];
81	  error?: string;
82	}
83	
84	export function RequisicaoChegadaModal({
85	  isOpen, onClose, requisicaoId, requisicaoNome,
86	  lojaDestinoId, lojaDestinoNome, items, onConcluida,
87	}: Props) {
88	  const [localItems, setLocalItems] = useState<ChegadaItem[]>([]);
89	  const [bipsLog, setBipsLog] = useState<BipBuffer[]>([]);
90	  const uidsLidosRef = useRef<Set<string>>(new Set());
91	  const [manual, setManual] = useState<ManualState>({ open: false, quantidade: "" });
92	  const [concluindo, setConcluindo] = useState(false);
93	  const [confirmandoFinalizar, setConfirmandoFinalizar] = useState(false);
94	
95	  useEffect(() => {
96	    if (!isOpen) return;
97	    setLocalItems(items.map((i) => ({ ...i })));
98	    setBipsLog([]);
99	    uidsLidosRef.current = new Set();
100	  }, [isOpen, items]);
101	
102	  // Marca a flag de chegada_iniciada_at na primeira interação
103	  const marcarChegadaIniciada = async () => {
104	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
105	    await (supabase.from("requisicoes") as any)
106	      .update({ chegada_iniciada_at: new Date().toISOString() })
107	      .eq("id", requisicaoId)
108	      .is("chegada_iniciada_at", null);
109	  };
110	
111	  const updateItemRow = async (
112	    itemId: number,
113	    novaQtd: string,
114	    via: "bip" | "manual",
115	    userId: string | null,
116	  ) => {
117	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
118	    return (supabase.from("requisicoes_itens") as any)
119	      .update({
120	        quantidade_recebida: novaQtd,
121	        recebida_via: via,
122	        recebida_at: new Date().toISOString(),
123	        recebida_por: userId,
124	      })
125	      .eq("id", itemId);
126	  };
127	
128	  const handleBip = async (payload: ScannedPayload) => {
129	    if (!payload.uid) {
130	      playErrorSound();
131	      toast.error("Etiqueta sem UID — não rastreável");
132	      return;
133	    }
134	    if (uidsLidosRef.current.has(payload.uid)) {
135	      playErrorSound();
136	      toast.error("Caixa já bipada nesta chegada");
137	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
138	      return;
139	    }
140	
141	    await marcarChegadaIniciada();
142	
143	    // Buscar dados da etiqueta para saber produto e quantidade
144	    const { data: etiquetaData, error: etiquetaErr } = await supabase
145	      .from("etiquetas_qr")
146	      .select("quantidade_interna, produto_master_id, lote_id")
147	      .eq("uid", payload.uid)
148	      .maybeSingle();
149	
150	    if (etiquetaErr) {
151	      playErrorSound();
152	      toast.error(`Falha ao ler etiqueta: ${etiquetaErr.message}`);
153	      return;
154	    }
155	
156	    const qty = Number(etiquetaData?.quantidade_interna ?? payload.qty ?? 1);
157	    const masterId = etiquetaData?.produto_master_id ?? null;
158	    const loteId = (etiquetaData as { lote_id?: string | null } | null)?.lote_id ?? null;
159	
160	    // RPC de marcação de conferência (NÃO mexe em estoque — só registra o bip)
161	    // @ts-expect-error RPC nova ainda não regenerada nos tipos
162	    const { data: marcRes, error: marcErr } = await (supabase.rpc as any)(
163	      "marcar_conferencia_requisicao",
164	      {
165	        p_uid: payload.uid,
166	        p_requisicao_id: requisicaoId,
167	        p_loja_id: lojaDestinoId,
168	        p_meta: {
169	          quantidade_interna: qty,
170	          produto_master_id: masterId,
171	          lote_id: loteId,
172	        },
173	      },
174	    );
175	
176	    if (marcErr) {
177	      playErrorSound();
178	      toast.error(`Falha ao registrar conferência: ${marcErr.message}`);
179	      return;
180	    }
181	
182	    const marcResult = marcRes as { ok: boolean; erro?: string; alertas?: string[] } | null;
183	    if (!marcResult?.ok) {
184	      playErrorSound();
185	      toast.error(marcResult?.erro || "Erro ao registrar bip de conferência");
186	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
187	      return;
188	    }
189	
190	    (marcResult.alertas ?? []).forEach((a) => {
191	      playWarningSound();
192	      toast.warning(a);
193	    });
194	
195	    const target = localItems.find((i) => i.masterId === masterId);
196	    if (!target) {
197	      playWarningSound();
198	      if (navigator.vibrate) navigator.vibrate([100, 50, 100]);
199	      toast.warning(`Produto #${masterId} NÃO está nesta requisição`);
200	      uidsLidosRef.current.add(payload.uid);
201	      return;
202	    }
203	
204	    // Soma à quantidade_recebida atual
205	    const baseAtual = Number(target.quantidade_recebida || "0") || 0;
206	    const novaQtdNum = baseAtual + qty;
207	
208	    const { data: { user } } = await supabase.auth.getUser();
209	    const { error: upErr } = await updateItemRow(target.id, String(novaQtdNum), "bip", user?.id ?? null);
210	    if (upErr) {
211	      playErrorSound();
212	      toast.error(`Erro ao salvar conferência: ${upErr.message}`);
213	      return;
214	    }
215	
216	    playSuccessSound();
217	    if (navigator.vibrate) navigator.vibrate(80);
218	    toast.success(`${target.nome_produto} +${qty} un`);
219	
220	    setLocalItems((prev) =>
221	      prev.map((i) => i.id === target.id
222	        ? { ...i, quantidade_recebida: String(novaQtdNum), recebida_via: "bip", recebida_at: new Date().toISOString() }
223	        : i),
224	    );
225	    setBipsLog((prev) => [
226	      { itemId: target.id, uid: payload.uid, qty, embalagem: null, bipadoAt: Date.now() },
227	      ...prev,
228	    ]);
229	    uidsLidosRef.current.add(payload.uid);
230	  };
231	
232	  const scanner = useEtiquetaScanner({
233	    enabled: isOpen,
234	    onScan: handleBip,
235	    cameraElementId: "chegada-qr-reader",
236	    onInvalid: () => toast.error("QR ilegível"),
237	    onDuplicate: () => {
238	      playErrorSound();
239	      toast.error("Esta etiqueta já foi bipada");
240	    },
241	  });
242	
243	  const askManual = (item: ChegadaItem) => {
244	    const restante = Math.max(0, item.quantidade_solicitada - (Number(item.quantidade_recebida || "0") || 0));
245	    setManual({
246	      open: true,
247	      item,
248	      quantidade: String(restante > 0 ? restante : item.quantidade_solicitada),
249	    });
250	  };
251	
252	  const confirmManual = async () => {
253	    if (!manual.item) return;
254	    const qty = Number(manual.quantidade);
255	    if (!Number.isFinite(qty) || qty < 0) {
256	      toast.error("Quantidade inválida");
257	      return;
258	    }
259	    await marcarChegadaIniciada();
260	    const { data: { user } } = await supabase.auth.getUser();
261	    const { error } = await updateItemRow(manual.item.id, String(qty), "manual", user?.id ?? null);
262	    if (error) {
263	      toast.error(`Erro ao salvar: ${error.message}`);
264	      return;
265	    }
266	    setLocalItems((prev) =>
267	      prev.map((i) => i.id === manual.item!.id
268	        ? { ...i, quantidade_recebida: String(qty), recebida_via: "manual", recebida_at: new Date().toISOString() }
269	        : i),
270	    );
271	    setManual({ open: false, quantidade: "" });
272	    toast.success(`${manual.item.nome_produto}: ${qty} un (manual)`);
273	  };
274	
275	  const executarFinalizacao = async () => {
276	    setConcluindo(true);
277	    setConfirmandoFinalizar(false);
278	
279	    // Chamar dar_entrada_requisicao UMA vez — dá entrada no estoque de TODAS as etiquetas bipadas
280	    // @ts-expect-error RPC nova ainda não regenerada nos tipos
281	    const { data: entradaRes, error: entradaErr } = await (supabase.rpc as any)(
282	      "dar_entrada_requisicao",
283	      { p_requisicao_id: requisicaoId },
284	    );
285	
286	    if (entradaErr) {
287	      toast.error(`Erro ao dar entrada no estoque: ${entradaErr.message}`);
288	      setConcluindo(false);
289	      return;
290	    }
291	
292	    const resultado = entradaRes as DarEntradaResult | null;
293	    if (!resultado?.ok) {
294	      toast.error(resultado?.error || "Falha ao registrar entrada no estoque");
295	      setConcluindo(false);
296	      return;
297	    }
298	
299	    // Feedback de sucesso
300	    toast.success(
301	      `Entrada registrada: ${resultado.etiquetas_processadas} etiqueta(s), ${resultado.total_quantidade} unidade(s)`,
302	    );
303	
304	    if (resultado.ja_processadas > 0) {
305	      toast.info(`${resultado.ja_processadas} etiqueta(s) já haviam sido processadas anteriormente`);
306	    }
307	
308	    (resultado.alertas ?? []).forEach((a) => toast.warning(a));
309	
310	    // chegada_concluida_at/por é carimbado pela própria RPC dar_entrada_requisicao
311	    // (COALESCE, idempotente) — não duplicar a escrita aqui no client.
312	
313	    setConcluindo(false);
314	    onConcluida?.();
315	    onClose();
316	  };
317	
318	  const finalizarEDarEntrada = () => {
319	    // Se há itens sem conferência, pedir confirmação antes de finalizar parcialmente
320	    if (stats.conferidos < stats.totalItens) {
321	      setConfirmandoFinalizar(true);
322	      return;
323	    }
324	    void executarFinalizacao();
325	  };
326	
327	  const stats = useMemo(() => {
328	    const totalItens = localItems.length;
329	    const conferidos = localItems.filter((i) => (Number(i.quantidade_recebida || "0") || 0) > 0).length;
330	    const totalSolicitado = localItems.reduce((acc, i) => acc + (i.quantidade_solicitada || 0), 0);
331	    const totalRecebido = localItems.reduce((acc, i) => acc + (Number(i.quantidade_recebida || "0") || 0), 0);
332	    const caixasBipadas = bipsLog.length;
333	    const allConferidos = totalItens > 0 && conferidos === totalItens;
334	    return { totalItens, conferidos, totalSolicitado, totalRecebido, caixasBipadas, allConferidos };
335	  }, [localItems, bipsLog]);
336	
337	  return (
338	    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
339	      <DialogContent
340	        data-mia-modal="conferir-chegada-requisicao-nome"
341	        className="max-w-[100vw] sm:max-w-[98vw] w-full h-[100dvh] sm:h-[95vh] p-0 flex flex-col overflow-hidden bg-white dark:bg-[#0A0A0A] sm:rounded-[1.5rem] rounded-none"
342	      >
343	        {/* Header */}
344	        <div className="flex items-center justify-between gap-2 px-3 sm:px-5 py-2 sm:py-3 flex-shrink-0 border-b border-[#57715B]/10">
345	          <div className="flex items-center gap-2 sm:gap-3 min-w-0 flex-1">
346	            <Button
347	              data-mia-action="close"
348	              aria-label="Voltar"
349	              variant="ghost"
350	              size="icon"
351	              onClick={onClose}
352	              className="rounded-2xl hover:bg-[#57715B]/10 h-11 w-11 flex-shrink-0"
353	            >
354	              <ArrowLeft className="w-5 h-5 text-[#57715B]" />
355	            </Button>
356	            <div className="h-10 w-10 rounded-2xl bg-[#57715B]/10 flex items-center justify-center flex-shrink-0">
357	              <ScanBarcode className="h-5 w-5 text-[#57715B]" />
358	            </div>
359	            <div className="min-w-0 flex-1">
360	              <DialogTitle className="text-base sm:text-lg font-bold text-[#57715B] dark:text-[#8FAE94] truncate">
361	                Conferir chegada · {requisicaoNome}
362	              </DialogTitle>
363	              <p className="text-[11px] sm:text-xs text-muted-foreground flex items-center gap-1 truncate">
364	                <MapPin className="w-3 h-3 flex-shrink-0" /> <span className="truncate">{lojaDestinoNome}</span>
365	              </p>
366	            </div>
367	          </div>
368	          <div className="flex p-1 rounded-xl bg-white/60 dark:bg-zinc-800 border border-white/20 dark:border-white/10 flex-shrink-0">
369	            <button
370	              onClick={() => scanner.setScanMode("bluetooth")}
371	              aria-label="Scanner Bluetooth"
372	              className={cn(
373	                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
374	                scanner.scanMode === "bluetooth"
375	                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
376	                  : "text-muted-foreground hover:text-foreground",
377	              )}
378	            >
379	              <Bluetooth className="h-4 w-4" /> <span className="hidden sm:inline">Scanner</span>
380	            </button>
381	            <button
382	              onClick={() => scanner.setScanMode("camera")}
383	              aria-label="Scanner por câmera"
384	              className={cn(
385	                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
386	                scanner.scanMode === "camera"
387	                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
388	                  : "text-muted-foreground hover:text-foreground",
389	              )}
390	            >
391	              <Camera className="h-4 w-4" /> <span className="hidden sm:inline">Câmera</span>
392	            </button>
393	          </div>
394	        </div>
395	
396	        {/* Stats */}
397	        <div className="px-3 sm:px-5 py-3 flex-shrink-0 border-b border-[#57715B]/10 grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-3">
398	          <Stat label="Itens conferidos" value={`${stats.conferidos}/${stats.totalItens}`} />
399	          <Stat label="Caixas bipadas" value={String(stats.caixasBipadas)} icon={<Boxes className="w-3 h-3" />} />
400	          <Stat label="Un. recebidas" value={`${stats.totalRecebido}/${stats.totalSolicitado}`} />
401	          <Stat label="Bips" value={String(stats.caixasBipadas)} />
402	        </div>
403	
404	        {/* Scanner input invisível */}
405	        {scanner.scanMode === "bluetooth" && <input {...scanner.inputProps} />}
406	
407	        {/* Body */}
408	        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
409	          {scanner.scanMode === "camera" ? (
410	            <div className="w-full md:w-[260px] flex-shrink-0 border-b md:border-b-0 md:border-r border-[#57715B]/10 bg-black overflow-hidden relative">
411	              <div id={scanner.cameraElementId} className="w-full h-[200px] md:h-full" />
412	              <CameraScannerStatus
413	                starting={scanner.cameraStarting}
414	                error={scanner.cameraError}
415	                onRetry={scanner.retryCamera}
416	              />
417	            </div>
418	          ) : (
419	            <div
420	              className="w-full md:w-[200px] flex-shrink-0 border-b md:border-b-0 md:border-r border-[#57715B]/10 flex flex-col items-center justify-center p-5 cursor-pointer"
421	              onClick={() => document.querySelector<HTMLInputElement>("input[autofocus]")?.focus()}
422	            >
423	              <div className="w-20 h-20 rounded-full bg-[#57715B]/10 flex items-center justify-center relative">
424	                <Bluetooth className="w-9 h-9 text-[#57715B]" />
425	                <div
426	                  className="absolute inset-0 rounded-full border-[3px] border-[#57715B]/20 border-t-[#57715B] animate-spin"
427	                  style={{ animationDuration: "3s" }}
428	                />
429	              </div>
430	              <h3 className="text-sm font-bold text-[#57715B] dark:text-[#8FAE94] mt-4">Aguardando bip…</h3>
431	              <p className="text-[11px] text-muted-foreground text-center mt-1">
432	                Sem etiqueta? Marque manual no item.
433	              </p>
434	            </div>
435	          )}
436	
437	          {/* Lista de itens da requisição */}
438	          <div className="flex-1 flex flex-col overflow-hidden">
439	            <ScrollArea className="flex-1">
440	              <div className="p-2.5 space-y-2">
441	                {localItems.length === 0 ? (
442	                  <div className="flex flex-col items-center justify-center py-16 text-muted-foreground/40">
443	                    <Package className="w-12 h-12 mb-2" />
444	                    <p className="text-sm font-semibold">Sem itens nessa requisição</p>
445	                  </div>
446	                ) : (
447	                  localItems.map((item) => (
448	                    <ItemRow key={item.id} item={item} onMarcarManual={() => askManual(item)} />
449	                  ))
450	                )}
451	              </div>
452	            </ScrollArea>
453	          </div>
454	        </div>
455	
456	        {/* Footer */}
457	        <div
458	          className="px-3 sm:px-5 py-3 border-t border-[#57715B]/10 flex items-center justify-between gap-2 flex-shrink-0"
459	          style={{ paddingBottom: "calc(env(safe-area-inset-bottom) + 12px)" }}
460	        >
461	          <p className="text-[11px] sm:text-xs text-muted-foreground truncate">
462	            {stats.allConferidos
463	              ? "Todos os itens conferidos."
464	              : `${stats.totalItens - stats.conferidos} item(ns) pendente(s).`}
465	          </p>
466	          <div className="flex gap-2 flex-shrink-0">
467	            <Button
468	              data-mia-action="close"
469	              onClick={onClose}
470	              variant="outline"
471	              className="h-11 border-[#57715B]/20 hover:bg-[#57715B]/10"
472	            >
473	              Salvar e fechar
474	            </Button>
475	            <Button
476	              data-mia-action="finalizar-dar-entrada"
477	              onClick={finalizarEDarEntrada}
478	              disabled={concluindo}
479	              className={cn(
480	                "h-11",
481	                stats.allConferidos
482	                  ? "bg-emerald-600 hover:bg-emerald-700"
483	                  : "bg-[#57715B] hover:bg-[#465b49]",
484	                "text-white",
485	              )}
486	            >
487	              {concluindo ? "Finalizando…" : "Finalizar e dar entrada"}
488	            </Button>
489	          </div>
490	        </div>
491	      </DialogContent>
492	
493	      {/* Confirmação de finalização parcial */}
494	      <AlertDialog
495	        open={confirmandoFinalizar}
496	        onOpenChange={(open) => !open && setConfirmandoFinalizar(false)}
497	      >
498	        <AlertDialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
499	          <AlertDialogHeader>
500	            <AlertDialogTitle className="flex items-center gap-2">
501	              <AlertTriangle className="w-5 h-5 text-amber-600" />
502	              Finalizar parcialmente?
503	            </AlertDialogTitle>
504	            <AlertDialogDescription asChild>
505	              <div className="text-sm text-muted-foreground space-y-2">
506	                <p>
507	                  <strong className="text-foreground">
508	                    {stats.totalItens - stats.conferidos} item(ns)
509	                  </strong>{" "}
510	                  ainda não foram bipados.
511	                </p>
512	                <p>
513	                  O estoque será dado entrada apenas nas etiquetas bipadas (
514	                  {stats.caixasBipadas} caixa(s)). Os itens não conferidos ficam pendentes.
515	                </p>
516	              </div>
517	            </AlertDialogDescription>
518	          </AlertDialogHeader>
519	          <AlertDialogFooter>
520	            <AlertDialogCancel
521	              onClick={() => setConfirmandoFinalizar(false)}
522	              className="border-[#57715B]/20 hover:bg-[#57715B]/10"
523	            >
524	              Voltar e bipar
525	            </AlertDialogCancel>
526	            <AlertDialogAction
527	              onClick={() => void executarFinalizacao()}
528	              className="bg-[#57715B] hover:bg-[#465b49] text-white"
529	            >
530	              Finalizar mesmo assim
531	            </AlertDialogAction>
532	          </AlertDialogFooter>
533	        </AlertDialogContent>
534	      </AlertDialog>
535	
536	      {/* Manual entry */}
537	      <AlertDialog
538	        open={manual.open}
539	        onOpenChange={(open) => !open && setManual((s) => ({ ...s, open: false }))}
540	      >
541	        <AlertDialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
542	          <AlertDialogHeader>
543	            <AlertDialogTitle className="flex items-center gap-2">
544	              <Hand className="w-5 h-5" /> Marcar manual
545	            </AlertDialogTitle>
546	            <AlertDialogDescription asChild>
547	              <div className="space-y-3 pt-2">
548	                <p className="font-semibold text-foreground">{manual.item?.nome_produto}</p>
549	                <p className="text-xs text-muted-foreground">
550	                  Pedido: {manual.item?.quantidade_solicitada} un · Já recebido:{" "}
551	                  {manual.item?.quantidade_recebida || 0} un
552	                </p>
553	                <div>
554	                  <label className="text-xs uppercase tracking-wider font-bold text-muted-foreground block mb-1">
555	                    Quantidade recebida (un)
556	                  </label>
557	                  <Input
558	                    type="number"
559	                    min="0"
560	                    step="any"
561	                    value={manual.quantidade}
562	                    onChange={(e) => setManual((s) => ({ ...s, quantidade: e.target.value }))}
563	                    autoFocus
564	                    className="h-11 text-lg font-bold bg-white/60 dark:bg-black/20 border-[#57715B]/20 focus-visible:ring-[#57715B]/30"
565	                  />
566	                </div>
567	                <p className="text-xs text-amber-700 bg-amber-50 dark:bg-amber-900/20 rounded-md p-2">
568	                  Marcar manual NÃO gera movimentação de estoque automática (sem etiqueta = sem
569	                  rastreabilidade).
570	                </p>
571	              </div>
572	            </AlertDialogDescription>
573	          </AlertDialogHeader>
574	          <AlertDialogFooter>
575	            <AlertDialogCancel
576	              onClick={() => setManual((s) => ({ ...s, open: false }))}
577	              className="border-[#57715B]/20 hover:bg-[#57715B]/10"
578	            >
579	              Cancelar
580	            </AlertDialogCancel>
581	            <AlertDialogAction
582	              onClick={() => void confirmManual()}
583	              className="bg-[#57715B] hover:bg-[#465b49] text-white"
584	            >
585	              Confirmar
586	            </AlertDialogAction>
587	          </AlertDialogFooter>
588	        </AlertDialogContent>
589	      </AlertDialog>
590	    </Dialog>
591	  );
592	}
593	
594	function Stat({
595	  label,
596	  value,
597	  icon,
598	}: {
599	  label: string;
600	  value: string | number;
601	  icon?: React.ReactNode;
602	}) {
603	  return (
604	    <div className="text-center min-w-0">
605	      <p className="text-[9px] sm:text-[10px] uppercase tracking-widest text-muted-foreground font-bold truncate flex items-center gap-1 justify-center">
606	        {icon}
607	        {label}
608	      </p>
609	      <p className="text-xl sm:text-2xl font-black tabular-nums text-[#57715B]">{value}</p>
610	    </div>
611	  );
612	}
613	
614	function ItemRow({
615	  item,
616	  onMarcarManual,
617	}: {
618	  item: ChegadaItem;
619	  onMarcarManual: () => void;
620	}) {
621	  const recebido = Number(item.quantidade_recebida || "0") || 0;
622	  const solicitado = item.quantidade_solicitada || 0;
623	  const enviado = Number(item.quantidade_enviada || "0") || 0;
624	  const pct = solicitado > 0 ? Math.min(100, Math.round((recebido / solicitado) * 100)) : 0;
625	  const status: "vazio" | "parcial" | "completo" | "excesso" =
626	    recebido === 0
627	      ? "vazio"
628	      : recebido > solicitado
629	        ? "excesso"
630	        : recebido >= solicitado
631	          ? "completo"
632	          : "parcial";
633	  const ring =
634	    status === "completo"
635	      ? "border-emerald-500/40 bg-emerald-500/5"
636	      : status === "excesso"
637	        ? "border-amber-500/40 bg-amber-500/5"
638	        : status === "parcial"
639	          ? "border-[#57715B]/30 bg-[#57715B]/5"
640	          : "border-white/30 dark:border-white/10";
641	  const bg =
642	    status === "completo"
643	      ? "bg-emerald-500"
644	      : status === "excesso"
645	        ? "bg-amber-500"
646	        : status === "parcial"
647	          ? "bg-[#57715B]"
648	          : "bg-zinc-300 dark:bg-zinc-700";
649	  return (
650	    <div className={cn("rounded-xl border-2 p-3", ring)}>
651	      <div className="flex items-start justify-between gap-2 mb-1.5">
652	        <div className="min-w-0 flex-1">
653	          <p className="text-sm font-semibold leading-tight truncate flex items-center gap-2">
654	            {status === "completo" && (
655	              <CheckCircle2 className="w-4 h-4 text-emerald-600 flex-shrink-0" />
656	            )}
657	            {status === "excesso" && (
658	              <AlertTriangle className="w-4 h-4 text-amber-600 flex-shrink-0" />
659	            )}
660	            <span className="truncate">{item.nome_produto}</span>
661	          </p>
662	          <p className="text-[11px] text-muted-foreground mt-0.5">
663	            Pedido <b>{solicitado}</b> un · Expedido <b>{enviado || 0}</b> un
664	            {item.recebida_via && (
665	              <span
666	                className={cn(
667	                  "ml-2 inline-block px-1.5 py-0.5 rounded text-[9px] font-bold uppercase tracking-wider",
668	                  item.recebida_via === "bip"
669	                    ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300"
670	                    : "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300",
671	                )}
672	              >
673	                {item.recebida_via}
674	              </span>
675	            )}
676	          </p>
677	        </div>
678	        <div className="flex items-center gap-2 flex-shrink-0">
679	          <span
680	            className={cn(
681	              "text-sm font-bold tabular-nums",
682	              status === "completo"
683	                ? "text-emerald-700"
684	                : status === "excesso"
685	                  ? "text-amber-700"
686	                  : "text-foreground",
687	            )}
688	          >
689	            {recebido}/{solicitado}
690	          </span>
691	          <Button
692	            data-mia-action="marcar-manual"
693	            size="sm"
694	            variant="outline"
695	            className="h-8 gap-1 text-[11px] border-[#57715B]/20 hover:bg-[#57715B]/10"
696	            onClick={onMarcarManual}
697	          >
698	            <Hand className="w-3 h-3" /> Manual
699	          </Button>
700	        </div>
701	      </div>
702	      <div className="w-full h-1.5 bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden">
703	        <div
704	          className={cn("h-full rounded-full transition-all duration-500", bg)}
705	          style={{ width: `${pct}%` }}
706	        />
707	      </div>
708	    </div>
709	  );
710	}
